import { _decorator, Component, Node } from 'cc';
import { World } from '../Engine/World';
import { Bus } from '../Engine/Bus';
import { ViewRegistry } from '../Engine/ViewRegistry';
import { FixedTick } from '../Engine/Tick';
import { GameData } from '../Core/Data/GameData';
import { BulletView } from './View/BulletView';
import { PlayerView } from './View/PlayerView';
import { EnemyView } from './View/EnemyView';
import { FireSystem } from './System/FireSystem';
import { BulletSpawnSystem } from './System/BulletSpawnSystem';
import { PlayerControlSystem } from './System/PlayerControlSystem';
import { EnemySpawnSystem } from './System/EnemySpawnSystem';
import { MovementSystem } from './System/MovementSystem';
import { CombatSystem } from './System/CombatSystem';
import { DamageSystem } from './System/DamageSystem';
import { BattleStateSystem } from './System/BattleStateSystem';
import { OutOfBoundsSystem } from './System/OutOfBoundsSystem';
import { Plane } from './Entity/Plane';
import { BattleInputHandler } from './BattleInputHandler';
import { BATTLE_EVENT } from './BattleEvents';
import { PauseButton } from '../UI/Common/PauseButton';
import { RestartButton } from '../UI/Common/RestartButton';
import { BossView } from './View/BossView';
import { BossStageSystem } from './System/BossStageSystem';
import { InvincibleSystem } from './System/InvincibleSystem';
import { TurretSystem } from './System/TurretSystem';
import { BossHealthUI } from '../UI/Battle/BossHealthUI';
import { ExpSystem } from './System/ExpSystem';
import { expForLevel } from './Config/ExpConfig';
import { CardSystem } from './System/CardSystem';
import { CardApplySystem } from './System/CardApplySystem';
import { UpgradePanel } from '../UI/Battle/UpgradePanel';
import { WaveSystem } from './System/WaveSystem';
import { PlayerHealthUI } from '../UI/Battle/PlayerHealthUI';
import { ExpBarUI } from '../UI/Battle/ExpBarUI';

const { ccclass, property} = _decorator;

@ccclass('BattleScene')
export class BattleScene extends Component {
    @property(PauseButton)
    pauseButton: PauseButton = null!;

    @property(RestartButton)
    restartButton: RestartButton = null!;

    @property(BossHealthUI)             
    bossHealthUI: BossHealthUI = null!;

    @property(UpgradePanel)
    upgradePanel: UpgradePanel = null!;

    @property(PlayerHealthUI)
    playerHealthUI: PlayerHealthUI = null!;

    @property(ExpBarUI)
    expBarUI: ExpBarUI = null!;

    private _bus: Bus = null!;
    private _world: World = null!;
    private _views: ViewRegistry = null!;
    private _tick: FixedTick = null!;
    private _inputHandler: BattleInputHandler = null!;   
    private _stateSystem: BattleStateSystem = null!;    
    private _waveSystem: WaveSystem = null!;

    protected start(): void {

        GameData.init();
         
        this._bus = new Bus();
       
        this._buildWorld();

        // 监听游戏结束
        this._bus.on(BATTLE_EVENT.GAME_OVER, this._onGameOver, this);
        this._bus.on(BATTLE_EVENT.PAUSE_TOGGLE_REQUEST, this._onPauseToggleRequest, this);
        this._bus.on(BATTLE_EVENT.RESTART_REQUEST, this._onRestartRequest, this);
        this._bus.on(BATTLE_EVENT.CARDS_DRAWN, this._onCardsDrawn, this);
        this._bus.on(BATTLE_EVENT.CARD_SELECTED, this._onCardSelected, this);

       
        this.pauseButton.setup(this._bus);
        this.restartButton.setup(this._bus);
        this.bossHealthUI.setup(this._bus);
        this.upgradePanel.setup(this._bus);
        this.playerHealthUI.setup(this._bus);  
        this.expBarUI.setup(this._bus);  

        this._createPlayer();

        this._tick = this.node.addComponent(FixedTick);
        this._tick.setup(this._world, this._views);
        this._tick.begin();

        this._inputHandler = this.node.addComponent(BattleInputHandler);
        this._inputHandler.setup(this._bus);

        this._waveSystem.begin();
    }

    onDestroy(): void {
        this._bus?.off(BATTLE_EVENT.PAUSE_TOGGLE_REQUEST, this._onPauseToggleRequest, this);
        this._bus?.off(BATTLE_EVENT.RESTART_REQUEST, this._onRestartRequest, this);
        this._bus?.off(BATTLE_EVENT.GAME_OVER, this._onGameOver, this);
        this._bus?.off(BATTLE_EVENT.CARDS_DRAWN, this._onCardsDrawn, this);
        this._bus?.off(BATTLE_EVENT.CARD_SELECTED, this._onCardSelected, this);
        this._tick?.stop();
        this._world?.destroy();
    }

    private _onPauseToggleRequest(): void {

        if (this._stateSystem && this._stateSystem.state === 'over') {
            return;
        }

        if (this._tick.isRunning) {
            this._pauseGame();
            this._bus.emit(BATTLE_EVENT.PAUSE_TOGGLED, true);
        } else {
            this._resumeGame();
            this._bus.emit(BATTLE_EVENT.PAUSE_TOGGLED, false);
        }
    }


    private _registerViewFactories(): void {
        this._views.registerFactory('bullet', (e) => {
            const node = new Node(`bullet_${e.id}`);
            return node.addComponent(BulletView);
            }
        );

        this._views.registerFactory('player', (e) => {
            const node = new Node(`player_${e.id}`);
            return node.addComponent(PlayerView);
            }
        );

        this._views.registerFactory('enemy', (e) => {
            const node = new Node(`enemy_${e.id}`);
            return node.addComponent(EnemyView);
            }
        );
        this._views.registerFactory('boss', (e) => {
            const node = new Node(`boss_${e.id}`);
            return node.addComponent(BossView);
        });
    }

    private _buildWorld(): void {
        this._views = new ViewRegistry(this.node);
        this._world = new World(this._bus, this._views);
        this._registerViewFactories();
        this._setupSystems();
    }

    private _setupSystems(): void{
        this._world.addSystem(new FireSystem());
        this._world.addSystem(new BulletSpawnSystem());
        this._world.addSystem(new PlayerControlSystem());
        this._world.addSystem(new InvincibleSystem()); 
        this._world.addSystem(new EnemySpawnSystem());
        this._world.addSystem(new MovementSystem());
        this._world.addSystem(new CombatSystem());
        this._world.addSystem(new DamageSystem());
        this._world.addSystem(new ExpSystem());
        this._world.addSystem(new CardApplySystem());    
        this._world.addSystem(new CardSystem());     
        this._world.addSystem(new BossStageSystem()); 
        this._world.addSystem(new TurretSystem()); 
        this._waveSystem = new WaveSystem();        
        this._world.addSystem(this._waveSystem);
        this._stateSystem = new BattleStateSystem();
        this._world.addSystem( this._stateSystem);
        this._world.addSystem(new OutOfBoundsSystem());
    }


    private _createPlayer():void{
        const player = new Plane('player');
        player.x = 0;
        player.y = -GameData.viewH / 2 + 100;
        player.hp = 100;
        player.maxHp = 100;
        player.exp = 0;
        player.level = 1;
        player.expToNext = expForLevel(1); 
        player.collisionRadius = 20;
        player.hitInvincibleDuration = 1.0;
        player.weapons.push({
            config: {
                fireInterval: 0.2,
                bulletType: 'blue',
                bulletSpeed: 400,
                bulletDamage: 10,
                fireDirX: 0,
                fireDirY: 1,
            },
            cooldownTimer: 0,
            enabled: true,
        });
        this._world.add(player);
        this._bus.emit(BATTLE_EVENT.PLAYER_HP_CHANGED, player.hp / player.maxHp);
        this._bus.emit(BATTLE_EVENT.EXP_CHANGED, player.exp, player.expToNext, player.level);
    }

    private _onGameOver(): void{
        console.log('[BattleScene] 游戏结束');
        this._pauseGame();
        if (this.pauseButton) this.pauseButton.setEnabled(false);
    }

    private _onRestartRequest(): void {   
        console.log('[BattleScene] 重开');

        this._pauseGame();
        this._world.destroy();

        this._buildWorld();
        

        this._createPlayer();

        this._tick.setup(this._world, this._views);
        
        this._resumeGame();
        this._waveSystem.begin(); 

        //  恢复暂停按钮
        if (this.pauseButton) this.pauseButton.setEnabled(true);
        this._bus.emit(BATTLE_EVENT.PAUSE_TOGGLED, false);
    }


    private _onCardsDrawn(): void {
        console.log('[BattleScene] 选卡，暂停');
        this._pauseGame();
        if (this.pauseButton) this.pauseButton.setEnabled(false);
    }

    private _onCardSelected(): void {
        console.log('[BattleScene] 选卡完成，恢复');
        this._resumeGame();
        if (this.pauseButton) this.pauseButton.setEnabled(true); 
    }

    private _pauseGame(): void {
        this._tick.stop();
        if (this._inputHandler) this._inputHandler.enabled = false;
    }

    private _resumeGame(): void {
        this._tick.begin();
        if (this._inputHandler) this._inputHandler.enabled = true;
    }

}


